  "apitokens.secret.done": "Erledigt – Geheimnis ausblenden",
  "apitokens.sealed": "Token «{name}» erzeugt und im Vault als «{secret}» abgelegt. Das Geheimnis hat den Server nicht verlassen.",
  "apitokens.sealed.done": "Fertig",
  "apitokens.created": "Token erzeugt",
  "apitokens.createdSealed": "Token erzeugt und im Vault abgelegt",
