  "storage.reclaim.on": "Das WAL wird mit jedem Checkpoint kompaktiert (Takt: {every}). Es behält nur, was seit dem letzten Checkpoint dazugekommen ist und was ein Verbraucher noch braucht.",
  "storage.reclaim.off": "Das WAL wird nicht kompaktiert und wächst darum weiter. Dauerhaft einschalten mit --compact-wal oder ATLAS_COMPACT_WAL=true, einmalig mit «Einmal kompaktieren».",
  "storage.reclaim.last": "Letzter Durchlauf {when}:",
