  "storage.reclaim.compactOnce": "Einmal kompaktieren…",
  "storage.reclaim.confirm": "Das WAL jetzt einmal kompaktieren?\n\nAtlas löscht die WAL-Segmente, die ein geprüfter Checkpoint abdeckt und die kein Verbraucher mehr braucht. Der OpenSearch-Exporter und ein laufendes Backup halten Segmente zurück. Das lässt sich nicht rückgängig machen.\n\nDer Durchlauf prüft dabei die Checkpoints. Bei einem grossen Zustandsspeicher kann das einige Minuten dauern.",
  "storage.reclaim.running": "Läuft…",
  "storage.reclaim.noAnswer": "Keine Antwort erhalten ({error}). Der Durchlauf läuft möglicherweise weiter. Lade die Seite in einigen Minuten neu.",
  "storage.reclaim.failed": "Abgelehnt: {error}",
  "storage.reclaim.checkpointFailed": "Der Checkpoint ist fehlgeschlagen: {error}",
  "storage.reclaim.checkpointAt": "Checkpoint bei Position {position}.",
  "storage.reclaim.checkpointNone": "Kein neuer Checkpoint: Seit dem letzten ist nichts dazugekommen.",
  "storage.reclaim.compactionFailed": "Die Kompaktierung ist fehlgeschlagen: {error}",
  "storage.reclaim.removed.one": "Ein WAL-Segment entfernt.",
  "storage.reclaim.removed.other": "{n} WAL-Segmente entfernt.",
  "storage.reclaim.skipped": "Kompaktierung übersprungen: {note}",
  "storage.reclaim.nothing": "Kein WAL-Segment entfernt: Keines war durch einen geprüften Checkpoint und alle Verbraucher abgedeckt.",
  "storage.reclaim.purgeHint": "Beendete Instanzen löschst du pro Prozess unter Operations, im Menü ⋯ der Zeile. Löschen allein gibt keinen Platz frei, erst die Kompaktierung danach.",
