  "connections.title": "Verbundene Konten",
  "connections.intro": "Hier verknüpfst du ein externes Konto, zum Beispiel dein Microsoft-Konto, und bestimmst, welche Worker in deinem Namen handeln dürfen. Eine neue Verbindung erlaubt noch keinem Worker etwas – das entscheidest du hier.",
  "connections.unavailable": "Delegierte Verbindungen brauchen den Vault, und der ist auf diesem Server ausgeschaltet.",
  "connections.signIn": "Melde dich an, um deine verbundenen Konten zu sehen.",
  "connections.link": "Mit {provider} verknüpfen",
  "connections.link.unconfigured": "Auf diesem Server ist die Kontoverknüpfung noch nicht eingerichtet. Das kann nur eine Administratorin oder ein Administrator ändern.",
  "connections.link.unconfiguredAdmin": "Auf diesem Server ist die Kontoverknüpfung noch nicht eingerichtet. Du richtest sie unter Administration → Security ein; dort steht auch, was es bei Microsoft dafür braucht.",
  "connections.link.setUp": "Kontoverknüpfung einrichten",
  "connections.link.privacy": "Du meldest dich direkt beim Anbieter an. atlas sieht dein Passwort nie; Mehrfaktor-Anmeldung und die Regeln deiner Organisation gelten wie gewohnt.",
  "connections.linked.title": "Konto verknüpft.",
  "connections.linked.next": "Wähle jetzt unten, welche Worker über diese Verbindung in deinem Namen handeln dürfen. Bis dahin darf es keiner.",
  "connections.failed.title": "Die Verknüpfung ist nicht zustande gekommen.",
  "connections.failed.hint": "Es wurde nichts gespeichert. Versuche es erneut; wenn es wieder scheitert, findet ein Administrator den Grund im Audit-Log.",
  "connections.identities.title": "Verknüpfte Konten",
  "connections.identities.empty": "Du hast noch kein Konto verknüpft.",
  "connections.identity.keyTitle": "So erkennt atlas das Konto: Anbieter, Mandant und die unveränderliche Kennung beim Anbieter – nie die E-Mail-Adresse.",
  "connections.col.account": "Konto",
