  "security.title": "Sicherheit",
  "security.intro": "Welche Worker als wer handeln und nach welcher Policy. atlas entscheidet jede geregelte Aktion vor ihrer Ausführung und hält den Entscheid im Log fest.",
  "security.denied": "Diese Seite ist Administratoren vorbehalten.",
  "security.link.title": "Kontoverknüpfung (Microsoft)",
  "security.link.intro": "Damit Personen ihr Microsoft-Konto verknüpfen und Worker in ihrem Namen handeln lassen können, braucht atlas eine App-Registrierung in Microsoft Entra. Ohne sie kann niemand ein Konto verknüpfen, und der Eintrag «Connected accounts» erscheint im Kontomenü nur, wo schon etwas verknüpft ist.",
  "security.link.status.off": "nicht eingerichtet",
  "security.link.status.console": "eingerichtet",
  "security.link.status.flags": "durch Startparameter eingerichtet",
  "security.link.status.flagsIncomplete": "Startparameter unvollständig",
  "security.link.status.unavailable": "nicht verfügbar",
  "security.link.unavailable": "Die Kontoverknüpfung braucht den Vault, und der ist auf diesem Server ausgeschaltet.",
  "security.link.flags": "Die Startparameter dieses Servers legen die Kontoverknüpfung fest (--link-microsoft-…). Hier lässt sie sich nur ansehen; ändern lässt sie sich dort – oder hier, sobald die Startparameter entfernt sind.",
  "security.link.flagsIncompleteHint": "Es fehlen Angaben, deshalb ist die Verknüpfung aus: Tenant-ID, Client-ID und Scopes sind nötig.",
  "security.link.steps": "Bei Microsoft (Entra Admin Center → App-Registrierungen):",
  "security.link.step1": "Neue Registrierung anlegen: unterstützte Kontotypen «Nur Konten in diesem Organisationsverzeichnis», Plattform «Web» und als Umleitungs-URI die Adresse unten.",
  "security.link.step2": "Unter «API-Berechtigungen» die delegierten Berechtigungen hinzufügen, die die Worker brauchen – für SharePoint Sites.ReadWrite.All oder, enger, Sites.Selected – und die Administratorzustimmung erteilen, wo der Tenant sie verlangt.",
  "security.link.step3": "Unter «Zertifikate & Geheimnisse» einen geheimen Clientschlüssel erstellen und seinen Wert kopieren; Entra zeigt ihn nur einmal.",
  "security.link.step4": "Verzeichnis-ID (Mandant), Anwendungs-ID (Client), die Berechtigungen und den Schlüssel hier eintragen und speichern. Ab dann können Personen ihr Konto verknüpfen.",
  "security.link.redirect": "Umleitungs-URI",
  "security.link.copy": "Kopieren",
  "security.link.copied": "Kopiert",
  "security.link.copyFailed": "Kopieren ging nicht – markiere die Adresse und kopiere sie selbst.",
  "security.link.redirectDerived": "atlas leitet diese Adresse aus der aktuellen Anfrage ab. Ist der Server von aussen unter einer anderen Adresse erreichbar, muss --external-url gesetzt sein, sonst passt sie nicht zur Registrierung.",
  "security.link.tenant": "Verzeichnis-ID (Mandant)",
  "security.link.client": "Anwendungs-ID (Client)",
  "security.link.scopes": "Delegierte Berechtigungen (Scopes)",
  "security.link.scopesHint": "Scopes durch Leerzeichen trennen; openid, profile und offline_access fügt atlas selbst hinzu.",
  "security.link.secret": "Geheimer Clientschlüssel (Wert)",
  "security.link.secretKept": "gespeichert – leer lassen, um ihn zu behalten",
  "security.link.secretSet": "gesetzt",
  "security.link.secretUnset": "nicht gesetzt",
  "security.link.secretHint": "Der Schlüssel liegt verschlüsselt im Vault und wird nie wieder angezeigt; kein Worker und keine Secrets-Route erreicht ihn.",
  "security.link.save": "Speichern",
  "security.link.saved": "Gespeichert – Personen können ihr Konto jetzt verknüpfen",
  "security.link.remove": "Einrichtung entfernen",
  "security.link.removed": "Entfernt – niemand kann mehr ein Konto verknüpfen",
  "security.link.removeConfirm": "Die Kontoverknüpfung entfernen?\n\nDanach kann niemand mehr ein Konto verknüpfen.",
  "security.link.removeConfirmConnections": "Die Kontoverknüpfung entfernen?\n\nDanach kann niemand mehr ein Konto verknüpfen. Die bestehenden Verbindungen ({n}) bleiben erhalten, können aber nicht handeln, bis die Verknüpfung für ihren Tenant wieder eingerichtet ist.",
  "security.link.changeConfirm": "Tenant oder Client-ID ändern?\n\nEs bestehen {n} Verbindungen. Mit einer anderen App-Registrierung müssen sich ihre Besitzer neu anmelden; in einem anderen Tenant können sie nicht mehr handeln.",
  "security.link.stranded": "{n} Verbindungen können zurzeit nicht handeln: Sie gehören zu einem Tenant, für den die Verknüpfung nicht eingerichtet ist. Ihre Besitzer oder eine Administratorin können sie widerrufen.",
  "security.readiness.title": "Bereitschaft",
  "security.readiness.intro": "Jeder konfigurierte Worker: ob seine Aktionen geregelt sind, wie, und wo seine Zugangsdaten liegen. Hier stellst du einen Worker um.",
  "security.readiness.empty": "Keine Worker konfiguriert.",
