  "security.readiness.shadowWarning": "Mindestens ein Worker steht im Schattenmodus: Entscheide werden aufgezeichnet, aber nichts wird verhindert. Das ist keine Durchsetzung.",
  "security.enforcement.off": "aus",
  "security.enforcement.shadow": "Schatten",
