  "security.note.notGovernable": "Dieser Worker-Typ lässt sich in dieser Version noch nicht regeln.",
  "security.note.shadow": "Entscheide werden aufgezeichnet und blockieren nie – das ist keine Durchsetzung.",
  "security.note.cooperative": "Kooperativ durchgesetzt: Eine Ablehnung lässt den Job scheitern, und ein Abschluss ohne Erlaubnis wird abgewiesen – die Zugangsdaten hält aber der Worker selbst.",
  "security.note.credential": "An den Zugangsdaten durchgesetzt: atlas gibt sie nur bei einer Erlaubnis heraus und nur an Worker-Instanzen, die atlas selbst gestartet hat.",
