  // The Events page (events.js; ADR-0435, ADR-0447, ADR-0446). The server sends ids
  // — an event's kind and stability, a channel, an element's role, a finding's rule —
  // and these are the words for them. An event's meaning comes from the catalogue,
  // which writes it in both languages. The sentences the server composes — who
  // produces an event, who may receive it, what a finding names — stay in its English.
  "events.title": "Ereignisse",
  "events.intro": "Zwei Listen. Die erste zeigt, was atlas selbst aussendet: seinen Vertrag, gegen den Code geprüft. Die zweite zeigt, was die Modelle dieser Installation werfen, senden und empfangen. Sie wird aus den deployten Definitionen gelesen, verspricht deshalb nichts und zeigt, was nicht stimmt. Ein Signal oder eine Nachricht eines eigenen Modells steht in der zweiten Liste, nie in der ersten.",
  "events.loading": "Wird geladen …",
  "events.catalog.title": "Ereignisse, die atlas aussendet",
  "events.catalog.intro": "Die Signale und Nachrichten der Systemprozesse von atlas, der CloudEvents-Feed und die Log-Zeilen, die dazu gehören. Jeder Eintrag sagt, was geschehen ist, wenn er ausgesendet wird, was er trägt – Personendaten markiert – und wer ihn empfangen darf. Ein Modell hört mit einem Signal-Start oder -Catch auf den Namen; ein System ausserhalb von atlas liest den Feed. Ein Klick auf eine Zeile öffnet ihre Einzelheiten.",
