  "events.own.title": "Signale und Nachrichten dieser Installation",
  "events.own.intro": "Jeder Signal- und Nachrichtenname, den die deployten Modelle werfen, senden oder empfangen: wer was tut, in welchem Projekt und welcher Version, und was mit dem Namen nicht stimmt – ein Wurf, den niemand empfängt, ein Empfänger, dessen Namen niemand wirft, ein Name, der zwei Projekte koppelt, ein Modell, das für atlas spricht. Wer einen Namen <code>atlas.*</code> empfängt, steht in der ersten Liste unter «Wer gerade zuhört», nur für Administratoren sichtbar. Was tatsächlich gesendet wurde und wo es ankam, zeigt das <a href=\"#/operations/event-log\">Event log</a>. Ein Klick auf eine Zeile öffnet ihre Einzelheiten.",
