  "events.own.unseen.signal": "Nur ein Modell wirft ein Signal: Keine Route sendet eines.",
  "events.own.log": "Was unter diesem Namen gesendet wurde: das Event log",
  "events.own.versions.signal": "Alle deployten Versionen sind aufgeführt; die Befunde lesen die neueste Version jedes Prozesses. Eine laufende Instanz einer älteren Version kann einen Namen noch werfen, den die neueste nicht mehr kennt, oder auf ihn warten. Ein Signal trägt jede Variable der Instanz, die es wirft: Hier wird keine Nutzlast versprochen.",
  "events.own.versions.message": "Alle deployten Versionen sind aufgeführt; die Befunde lesen die neueste Version jedes Prozesses. Eine laufende Instanz einer älteren Version kann einen Namen noch senden, den die neueste nicht mehr kennt, oder auf ihn warten. Eine Nachricht trägt jede Variable der Instanz, die sie sendet: Hier wird keine Nutzlast versprochen.",

