  // The decision editor (dmn-editor.js).
  "dmn.view.overview": "Übersicht (DRG)",
  "dmn.view.decision": "Entscheidung",
  "dmn.hint.tail": "<b>Speichern</b> legt einen Entwurf an, den nur du siehst; <b>Ins Modell speichern</b> schreibt die Entscheidung, die jeder Prozess auflöst, und ist das, was die nächste Veröffentlichung ausliefert; <b>Deployen</b> bringt diese Entscheidung allein als neue Version in die Engine. <b>Testen</b> führt sie mit Beispielwerten aus und zeigt, welche Regeln gegriffen haben — dabei wird nichts gespeichert oder deployt.",
  "dmn.hint.drd": "Zeichne den Entscheidungsanforderungsgraphen. Ein Knoten <b>Eingabedaten</b> ist etwas, das dieses Modell bekommt, eine <b>Entscheidung</b> enthält Logik, und ein <b>Wissensmodell</b> ist eine wiederverwendbare Funktion, die eine Entscheidung aufrufen kann. Öffne den Reiter einer Entscheidung, um ihre Logik zu modellieren.",
  "dmn.hint.literal": "Die Logik dieser Entscheidung ist ein einziger FEEL-Ausdruck: Was er ergibt, ist das Ergebnis der Entscheidung, unter der darunter genannten Variable. Ihre Eingaben sind, was der Anforderungsgraph ihr gibt — beides wird in eine Business Rule Task übernommen, die diese Entscheidung aufruft.",
  "dmn.hint.boxed": "Ein <b>Wissensmodell</b> ist eine wiederverwendbare FEEL-Funktion, keine Entscheidung: Kein Prozess ruft es auf. <b>F</b> ist die Ausdruckssprache, die Liste daneben sind die Parameter, die ein Aufrufer übergibt, der Rumpf wird mit ihnen ausgewertet, und <b>Result</b> nennt die Variable, an die eine Entscheidung das Ergebnis bindet, wenn sie dieses Modell aufruft.",
  "dmn.hint.list": "Die Logik dieser Entscheidung ist eine <b>Liste</b>: Jeder Eintrag ist ein FEEL-Ausdruck, und das Ergebnis der Entscheidung ist die Liste ihrer Werte, in dieser Reihenfolge. Ein Eintrag wie <code>{value: \"CC100\", label: \"Einkauf\"}</code> ist eine Option mit Bezeichnung. Eine Liste kann einem Auswahlfeld eines Formulars seine Optionen geben, und ihre Eingaben können aus anderen Feldern kommen — das Formular zeigt, was die neueste deployte Version für die dort getroffene Wahl ergibt.",
  "dmn.hint.table": "Modelliere die Entscheidungstabelle. Knoten <b>Eingabedaten</b> werden zu den Eingaben der Entscheidung, und die Ausgabespalte wird zu ihrer Ergebnisvariable — beides wird in eine Business Rule Task übernommen, die diese Entscheidung aufruft.",
  "dmn.column.added": "«{input}» als Eingabespalte von «{decision}» hinzugefügt.",
  "dmn.column.removeAsk.one": "Die Eingabespalte auch entfernen?",
  "dmn.column.removeAsk.other": "Die Eingabespalten auch entfernen?",
  "dmn.column.removeLine": "  • «{name}» in «{decision}»",
  "dmn.column.removeLineCount": " ({n} Spalten)",
  "dmn.column.removeWhy.one": "Nichts gibt der Entscheidung diesen Namen mehr, also liest diese Spalte einen Namen, der sich nicht auflösen lässt, und das Modell lässt sich nicht deployen.\n\nWer die Spalte entfernt, entfernt auch ihre Zelle in jeder Regel, und diese Zellen sind Logik, die jemand geschrieben hat — deshalb ist das eine Frage und geschieht nicht einfach. Abbrechen behält sie; die Befunde unter der Zeichenfläche zeigen auf sie.",
  "dmn.column.removeWhy.other": "Nichts gibt der Entscheidung diese Namen mehr, also lesen diese Spalten Namen, die sich nicht auflösen lassen, und das Modell lässt sich nicht deployen.\n\nWer eine Spalte entfernt, entfernt auch ihre Zelle in jeder Regel, und diese Zellen sind Logik, die jemand geschrieben hat — deshalb ist das eine Frage und geschieht nicht einfach. Abbrechen behält sie; die Befunde unter der Zeichenfläche zeigen auf jede davon.",
  "dmn.column.removed.one": "{n} Eingabespalte mit {with} entfernt — Ctrl+Z macht es rückgängig.",
  "dmn.column.removed.other": "{n} Eingabespalten mit {with} entfernt — Ctrl+Z macht es rückgängig.",
  "dmn.column.withRequirement.one": "der Anforderung",
  "dmn.column.withRequirement.other": "den Anforderungen",
  "dmn.draw.noView": "In dieser Ansicht lässt sich die Anforderung nicht zeichnen.",
