  "xml.hint.diagram": "Das ist das Diagramm, wie es auf der Zeichenfläche steht, gespeichert oder nicht. Korrigiere es hier und wähle <b>Übernehmen</b> (Ctrl+Enter): Das Diagramm wird aus dem Text neu aufgebaut. Übernehmen ist eine Änderung wie jede andere — <b>Speichern</b> entscheidet weiterhin, was behalten wird —, beginnt aber den Rückgängig-Verlauf neu.",
  "xml.hint.decision": "Das ist die Entscheidung, wie sie auf der Zeichenfläche steht, gespeichert oder nicht. Korrigiere sie hier und wähle <b>Übernehmen</b> (Ctrl+Enter): Die Entscheidung wird aus dem Text neu aufgebaut. Übernehmen ist eine Änderung wie jede andere — <b>Speichern</b> entscheidet weiterhin, was behalten wird —, beginnt aber den Rückgängig-Verlauf neu.",
