  "wt.Failure handling": "Fehlerbehandlung",
  "wt.How often the engine hands this task's job to a worker before giving up — the first attempt plus one per remaining count. When they are used up the failure raises an incident that parks the token until an operator resolves it. Leave empty for the default (3); 1 means a single attempt with no retry.": "Wie oft die Engine den Job dieser Task an einen Worker übergibt, bevor sie aufgibt — den ersten Versuch eingerechnet. Sind die Versuche aufgebraucht, löst der Fehlschlag einen Incident aus, der das Token parkt, bis ein Operator ihn behebt. Lass das Feld leer für den Standardwert (3); 1 bedeutet einen einzigen Versuch ohne Wiederholung.",
  "pnl.feel.sql.desc": "Eine Abfrage oder Anweisung auf einem Worker gegen eine {name}-Datenbank ausführen",
  "pnl.feel.sql.connectorHint": "Der konfigurierte Worker für {name}, auf dem diese Anweisung läuft, mit dem Namen, den er unter Workers in der Konsole trägt. Sein Connection-String ist dort im Vault versiegelt, oder ein Worker, den du selbst betreibst, liest ihn aus seiner eigenen Umgebung (ATLAS_{env}_<NAME>_DSN) — so oder so hält die Engine nie Zugangsdaten einer Datenbank (ADR-0173). Ist das Mockup für Datenbanken eingeschaltet (Konsole › Workers, oder ATLAS_{env}_MOCK auf einem Worker, den du selbst betreibst), beantwortet derselbe Worker die Task stattdessen aus vorbereiteten Antworten in seinem Speicher, sodass sich das Modell ohne Datenbank ausprobieren lässt (ADR-0221).",
  "pnl.feel.sql.statementHint": "Literales SQL — dieses Feld hat absichtlich keinen fx-Schalter. Eine aus Prozessdaten zusammengesetzte Anweisung wäre eine Injection, darum gelangen Werte nur als gebundene Parameter (unten) hinein. {name} verwendet Platzhalter der Form {placeholder}.",
  "pnl.feel.sql.paramsHintNamed": "Eine Prozessvariable, die an die Platzhalter der Anweisung gebunden wird: Ein JSON-Array bindet nach Reihenfolge, ein JSON-Objekt nach Namen ({name} unterstützt benannte Bindung). Lass das Feld leer bei einer Anweisung ohne Platzhalter.",
  "pnl.feel.sql.paramsHintOrdered": "Eine Prozessvariable, die an die Platzhalter der Anweisung gebunden wird: als JSON-Array, in Reihenfolge. {name} kennt keine benannten Parameter, darum wird ein Objekt abgelehnt statt stillschweigend umgeordnet. Lass das Feld leer bei einer Anweisung ohne Platzhalter.",
  "wt.Database": "Datenbank",
  "wt.Statement": "Anweisung",
  "wt.Output": "Ausgabe",
  "wt.Query — many rows": "Abfrage — viele Zeilen",
  "wt.Query one — a single row": "Einzelabfrage — eine Zeile",
  "wt.Execute — insert/update/delete": "Ausführen — insert/update/delete",
  "wt.SQL statement": "SQL-Anweisung",
  "wt.Parameters variable": "Parametervariable",
  "wt.Result variable": "Ergebnisvariable",
  "wt.Receives the rows (query), the single row (query one), or the affected-row count (execute). Required except for execute, where it may be left empty to discard the count.": "Erhält die Zeilen (Abfrage), die einzelne Zeile (Einzelabfrage) oder die Anzahl betroffener Zeilen (Ausführen). Pflichtfeld, ausser bei Ausführen: Dort darf es leer bleiben, um die Anzahl zu verwerfen.",
  "wt.Maximum rows": "Maximale Zeilenzahl",
  "wt.Caps the result set. A query returning more fails the job rather than truncating, because a short result set is a wrong answer, not a partial one. Empty uses the worker's default of 1000.": "Begrenzt die Ergebnismenge. Liefert eine Abfrage mehr Zeilen, schlägt der Job fehl, statt abzuschneiden — denn eine gekürzte Ergebnismenge ist eine falsche Antwort, keine unvollständige. Ist das Feld leer, gilt der Standardwert des Workers von 1000.",
  "pnl.feel.detail.variable": "Variable",
  "pnl.feel.detail.keyword": "Schlüsselwort",
  "pnl.feel.detail.literal": "Literal",
