  "pnl.feel.ref.noteAccount": "Der Name, wie das Konto jetzt lautet — für diese Ansicht aufgelöst und nie in der Instanz gespeichert (ADR-0314).",
  "pnl.feel.ref.noteProcess": "Der Prozess, wie er jetzt deployt ist — nicht unbedingt die Version, mit der diese Instanz gestartet ist.",
