  "pnl.ops.googlecontacts.area.directory": "Verzeichnis",
  "pnl.ops.googlecontacts.maxHint.search": "Wie viele Treffer das Ergebnis enthält, in Googles Rangfolge; höchstens {max}. Eine Suche antwortet mit ihren besten Treffern, weitere werden einfach nicht geliefert. Leer verwendet {default}.",
  "pnl.ops.googlecontacts.result.get": "Der Kontakt als ein Objekt: id, displayName, givenName, familyName, email, emails, phone, phones, organization, jobTitle, department, address, addresses, birthday, notes, fields (die benutzerdefinierten Felder nach Name) und groups (die Labels). Ein Schlüssel, für den der Kontakt keinen Wert hat, ist null, eine Liste leer.",
  "pnl.ops.googlecontacts.result.directory": "Eine Liste von Personen aus dem Verzeichnis, in der Form eines Kontakts; ihre id ist ein Profil, kein Kontakt, und lässt sich daher weder ändern noch mit einem Label versehen.",
  "pnl.ops.googlecontacts.result.saved": "Der Kontakt, wie Google ihn danach führt, mit seiner id — behalte ihn, um den Kontakt später anzusprechen. Leer lassen, um ihn zu verwerfen.",
  "pnl.ops.googlecontacts.query.search": "Freitext, den Google als Präfix mit Namen, E-Mail-Adressen, Telefonnummern und Organisationen vergleicht. Google antwortet aus einem Suchcache, der hinter jüngsten Änderungen zurückliegen kann: Um zu entscheiden, ob es einen Kunden gibt, verwende stattdessen «Kontakte finden».",
  "pnl.ops.googlecontacts.query.directory": "Ein Präfix eines Namens oder einer E-Mail-Adresse von jemandem in der Workspace-Organisation. Braucht den Verzeichnis-Scope in den Zugangsdaten des Workers.",
