  "pnl.ops.carddav.area.group": "Gruppe",
  "pnl.ops.carddav.maxHint.search": "Wie viele Treffer das Ergebnis enthält, in der Reihenfolge des Adressbuchs (Nachname, dann Vorname); höchstens {max}. Eine Suche antwortet mit ihren ersten Treffern, weitere werden einfach nicht geliefert. Leer verwendet {default}.",
  "pnl.ops.carddav.result.get": "Der Kontakt als ein Objekt: id, displayName, givenName, familyName, email, emails, phone, phones, organization, jobTitle, department, address, addresses, birthday, notes, fields (die X-Eigenschaften der Karte nach Name) und groups. Ein Schlüssel, für den der Kontakt keinen Wert hat, ist null, eine Liste leer — dieselbe Form wie ein Kontakt aus Google Contacts.",
  "pnl.ops.carddav.result.saved": "Der Kontakt, wie das Adressbuch ihn danach führt, mit seiner id — behalte ihn, um den Kontakt später anzusprechen. Leer lassen, um ihn zu verwerfen.",
  "pnl.ops.carddav.query.search": "Text, der in einem Namen, der Organisation oder einer E-Mail-Adresse vorkommt, ohne Rücksicht auf Gross-/Kleinschreibung, oder Ziffern, die in einer Telefonnummer vorkommen. Um zu entscheiden, ob es einen Kunden gibt, verwende «Kontakte finden», das exakt vergleicht.",
