  "pnl.ops.entra.extra.invalid": "Weitere Attribute: kein gültiges JSON — {error}",
  "pnl.ops.entra.result.getUser": "Bei dieser Operation das Benutzer-Objekt (id, displayName, userPrincipalName, mail, …) — mit «Properties» genau die genannten Eigenschaften, z. B. assignedLicenses oder employeeId.",
  "pnl.ops.entra.result.getUserManager": "Bei dieser Operation das Objekt der vorgesetzten Person (id, displayName, mail, userPrincipalName, …) — nicht das des Benutzers. Mit «Properties» genau die genannten Eigenschaften der vorgesetzten Person. Ist keine vorgesetzte Person eingetragen, ist die Variable null — ein Gateway fragt das mit = <Variable> = null ab. Ein unbekannter Benutzer lässt die Task dagegen fehlschlagen; fängt ein Fehler-Grenzereignis den Code ENTRA_USER_NOT_FOUND, endet die Task stattdessen mit diesem BPMN-Fehler.",
