  "pnl.event.owner.ownedBy.one": "Gehört zur Produktaktion {owners} — die Bestellung sendet sie.",
  "pnl.event.owner.ownedBy.other": "Gehört zu den Produktaktionen {owners} — die Bestellung sendet sie.",
