  "pnl.event.sv.varName": "Name der Variable",
  "pnl.event.sv.filledByAtlas": "{path} wird von Atlas gefüllt",
  "pnl.event.sv.type": "Typ",
  "pnl.event.sv.remove": "Entfernen",
  "pnl.event.sv.removeConst": "Konstante entfernen",
  "pnl.event.sv.removeVar": "Variable entfernen",

  // The BPMN properties panel: panel core, part 1 — data object pickers, pool, process and collaboration panels, the General group, data associations and the per-element Implement sections (editor.js).
  "pnl.main.none": "— keine —",
