  "product.serviceLevel.title": "Servicestufe",
  "product.serviceLevel.hint": "Was das Produkt über seine Lieferung verspricht: ein Name, den der Shop zeigt, und eine Lieferfrist in Arbeitstagen (Montag bis Freitag) von der Genehmigung bis zum Beginn des Bezugs. Sie wird mit dem Release eingefroren und auf die Bestellposition kopiert, damit jede Lieferung an dem Versprechen gemessen wird, unter dem bestellt wurde. Leer lassen, wenn das Produkt nichts verspricht.",
