  "catalog.reporting.title": "Kundenverantwortliche",
  "catalog.reporting.about": "Die Mitglieder dieser Gruppen sehen im Shop unter «Organisation», was die Zielgruppe dieses Katalogs bezieht und bestellt hat – mit Namen, Lieferfristen und Preisen, auch als CSV. Jeder Abruf wird protokolliert. Nur die Eigentümerin bzw. der Eigentümer des Katalogs und Administratoren legen das fest.",
