  "blocks.intro": "Die Services, die die Product Owner im Wiki beschreiben, als Bausteine für Marktleistungen. Eine Seite, die noch kein Produkt nutzt, ist ein beschriebener, aber noch nicht angebotener Service. «Produkt anlegen» erstellt daraus ein Produkt im Entwurf und verknüpft die Seite.",
